171	    const timestamp = new Date().toISOString();
172	    const location = info.location ? ` ${info.location}` : '';
173	    const message = extractMessage(info);
174	
175	    return `${timestamp} [${info.level.toUpperCase()}]${location}: ${message}`;
176	  },
